/**
 *
 * BreadcrumbCurrent is a component that displays the current page in the breadcrumb.
 *
 * [Live Demo](https://www.primereact.org/breadcrumb/)
 *
 * @module BreadcrumbCurrent
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { BreadcrumbRootInstance } from './BreadcrumbRoot.types';
/**
 * Defines passthrough(pt) options type in BreadcrumbCurrent component.
 */
export type BreadcrumbCurrentPassThroughType<E> = PassThroughType<BreadcrumbCurrentInstance, E>;
/**
 * Defines passthrough(pt) options of BreadcrumbCurrent component.
 */
export interface BreadcrumbCurrentPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: BreadcrumbCurrentPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in BreadcrumbCurrent component.
 */
export interface BreadcrumbCurrentProps extends BaseComponentProps<BreadcrumbCurrentInstance, unknown, BreadcrumbCurrentPassThrough> {
}
/**
 * Defines valid state in BreadcrumbCurrent component.
 */
export interface BreadcrumbCurrentState {
}
/**
 * Defines the methods and properties exposed by BreadcrumbCurrent component.
 */
export interface BreadcrumbCurrentExposes {
    /**
     * Instance of the Breadcrumb component.
     */
    breadcrumb: BreadcrumbRootInstance | undefined | null;
}
/**
 * Instance of BreadcrumbCurrent component.
 */
export type BreadcrumbCurrentInstance = ComponentInstance<BreadcrumbCurrentProps, BreadcrumbCurrentState, BreadcrumbCurrentExposes>;
